using System;
using System.Drawing;
using System.Drawing.Printing;
using System.Windows.Forms;
using DichVuKhachSan.BLL;
using DichVuKhachSan.DTO;

namespace DichVuKhachSan
{
    public partial class FrmQuanLyHoaDon : Form
    {
        private readonly InvoiceBLL _bll = new InvoiceBLL(); private ComboBox _invoicePicker; private InvoiceDTO _current; private readonly PrintDocument _printer = new PrintDocument();
        public FrmQuanLyHoaDon() { InitializeComponent(); btnThanhToan.Click += Pay; btnInHoaDon.Click += Print; btnLuuHoaDon.Click += (_, __) => LoadInvoices(); btnThemDichVu.Enabled = false; btnThemDichVu.Text = "Chọn hóa đơn"; _printer.PrintPage += PrintPage; }
        private void FrmQuanLyHoaDon_Load(object sender, EventArgs e) { _invoicePicker = new ComboBox { DropDownStyle = ComboBoxStyle.DropDownList, Location = new Point(370, 16), Size = new Size(440, 25), Font = txtKhachHang.Font }; _invoicePicker.SelectedIndexChanged += (_, __) => ShowInvoice(_invoicePicker.SelectedItem as InvoiceDTO); panelTop.Controls.Add(_invoicePicker); cboThanhToan.Items.Clear(); cboThanhToan.Items.AddRange(new object[] { "Tiền mặt", "Chuyển khoản" }); cboThanhToan.SelectedIndex = 0; LoadInvoices(); }
        private void LoadInvoices() { try { _invoicePicker.DataSource = _bll.GetAllInvoices(); _invoicePicker.DisplayMember = "InvoiceCode"; _invoicePicker.ValueMember = "InvoiceId"; if (_invoicePicker.Items.Count == 0) { dgvChiTietHoaDon.Rows.Clear(); txtKhachHang.Clear(); lblTongTienVal.Text = "0 VNĐ"; } } catch (Exception ex) { MessageBox.Show("Không tải được hóa đơn: " + ex.Message); } }
        private void ShowInvoice(InvoiceDTO item) { if (item == null) return; _current = _bll.GetInvoiceById(item.InvoiceId); if (_current == null) return; txtKhachHang.Text = _current.CustomerName + (string.IsNullOrWhiteSpace(_current.RoomNumber) ? "" : " - Phòng " + _current.RoomNumber); dtpNgayLap.Value = _current.InvoiceDate; dgvChiTietHoaDon.Rows.Clear(); var n = 1; foreach (var d in _current.OrderDetails) dgvChiTietHoaDon.Rows.Add(n++, d.ServiceName, d.Quantity.ToString("0.##"), d.UnitPrice.ToString("#,##0"), d.LineTotal.ToString("#,##0")); lblTongTienVal.Text = _current.FinalAmount.ToString("#,##0") + " VNĐ"; cboThanhToan.Enabled = _current.PaymentStatus == "Unpaid"; btnThanhToan.Enabled = _current.PaymentStatus == "Unpaid"; btnThanhToan.Text = _current.PaymentStatus == "Paid" ? "Đã thanh toán" : _current.PaymentStatus == "Cancelled" ? "Đã hủy" : "✓ Thanh toán"; }
        private void Pay(object sender, EventArgs e) { if (_current == null || _current.PaymentStatus != "Unpaid") { MessageBox.Show("Hóa đơn này không thể thanh toán."); return; } var discountText = Microsoft.VisualBasic.Interaction.InputBox("Nhập số tiền giảm giá (0 nếu không giảm):", "Thanh toán", _current.DiscountAmount.ToString("0")); if (!decimal.TryParse(discountText, out var discount) || discount < 0 || discount > _current.TotalAmount) { MessageBox.Show("Giảm giá không hợp lệ."); return; } if (!_bll.PayInvoice(_current.InvoiceId, discount, cboThanhToan.Text, _current.Notes, out var err)) { MessageBox.Show(err); return; } MessageBox.Show("Thanh toán thành công."); LoadInvoices(); }
        private void Print(object sender, EventArgs e) { if (_current == null) { MessageBox.Show("Vui lòng chọn hóa đơn."); return; } using var dialog = new PrintDialog { Document = _printer, UseEXDialog = true }; if (dialog.ShowDialog() == DialogResult.OK) _printer.Print(); }
        private void PrintPage(object sender, PrintPageEventArgs e) { if (_current == null) return; var y = e.MarginBounds.Top; using var title = new Font("Segoe UI", 16, FontStyle.Bold); using var body = new Font("Segoe UI", 10); e.Graphics.DrawString("HOTEL SERVICE - HÓA ĐƠN", title, Brushes.Navy, e.MarginBounds.Left, y); y += 45; e.Graphics.DrawString("Mã: " + _current.InvoiceCode + "     Ngày: " + _current.InvoiceDate.ToString("dd/MM/yyyy HH:mm"), body, Brushes.Black, e.MarginBounds.Left, y); y += 25; e.Graphics.DrawString("Khách hàng: " + _current.CustomerName, body, Brushes.Black, e.MarginBounds.Left, y); y += 35; foreach (var d in _current.OrderDetails) { e.Graphics.DrawString(d.ServiceName + " x" + d.Quantity.ToString("0.##") + "    " + d.LineTotal.ToString("#,##0") + " VNĐ", body, Brushes.Black, e.MarginBounds.Left, y); y += 22; } y += 12; e.Graphics.DrawString("TỔNG THANH TOÁN: " + _current.FinalAmount.ToString("#,##0") + " VNĐ", title, Brushes.Black, e.MarginBounds.Left, y); }
    }
}
